(()=>{const root=document.querySelector('.bk-main');if(!root)return;const status=root.querySelector('[data-bk-status]');root.addEventListener('click',async e=>{const btn=e.target.closest('[data-bk-copy]');if(btn){try{await navigator.clipboard.writeText(btn.dataset.bkCopy);status.textContent=btn.dataset.bkCopy+' copied.';}catch{status.textContent='Copy unavailable. Select the visible color code.';}return;}if(e.target.closest('[data-bk-replay]')){const panel=root.querySelector('.bk-motion');const s=panel.querySelector('[data-bk-motion-status]');if(matchMedia('(prefers-reduced-motion: reduce)').matches){s.textContent='Reduced motion enabled; static mark shown.';return;}panel.classList.remove('is-playing');void panel.offsetWidth;panel.classList.add('is-playing');s.textContent='Playing the finite monogram assembly.';}});})();
